    14	import { getPlanLimits } from "@/config/plan-limits";
    15	import { formatLimit } from "@/lib/format";
    16	import { can } from "@/lib/permissions";
    17	import { useFormAction } from "@/hooks/use-form-action";
    18	import { inviteMemberSchema, type InviteMemberInput } from "@/schemas/member";
    19	import type { ActionResult } from "@/types/api";
    20	import type { LimitCheck } from "@/types/billing";
    21	import type { OrgId } from "@/types/common";
    22	import type { Actor, Invitation, Role } from "@/types/member";
    23	import type { ReactElement } from "react";
    24	import { organizationResource } from "../permission/resources";
    25	import { RoleSelect } from "./role-select";
    26	
    27	export type InviteMemberFormProps = {
    28	  orgId: OrgId;
    29	  actor: Actor;
    30	  seatCheck: LimitCheck;
    31	  onSubmit: (input: InviteMemberInput) => Promise<ActionResult<Invitation>>;
    32	};
    33	
    34	export function InviteMemberForm(
    35	  props: InviteMemberFormProps,
    36	): ReactElement | null {
    37	  const { orgId, actor, seatCheck, onSubmit } = props;
    38	
    39	  const [email, setEmail] = useState("");
    40	  const [role, setRole] = useState<Role>("member");
    41	  const [invalid, setInvalid] = useState<string | null>(null);
    42	
    43	  const { submit, pending, error } = useFormAction(onSubmit, {
    44	    onSuccess: () => setEmail(""),
    45	  });
    46	
    47	  // Hiding the form is not the enforcement — `inviteMemberAction` calls
    48	  // `assertCan` for the same pair — but offering an impossible action is worse
    49	  // than not offering it.
    50	  if (!can(actor, "member:invite", organizationResource(orgId))) return null;
    51	
    52	  // The quota number comes from the plan table, never from a literal.
    53	  const limits = getPlanLimits(seatCheck.plan);
    54	  const seatsExhausted = seatCheck.exceeded || seatCheck.remaining <= 0;
    55	
    56	  async function handleSubmit(): Promise<void> {
    57	    const parsed = inviteMemberSchema.safeParse({ orgId, email, role });
    58	    if (!parsed.success) {
    59	      setInvalid(parsed.error.issues[0]?.message ?? "Check the address");
    60	      return;
    61	    }
    62	    setInvalid(null);
    63	    await submit(parsed.data);
    64	  }
    65	
    66	  return (
    67	    <div className="invite-member-form space-y-3">
    68	      {seatsExhausted ? (
    69	        <Alert tone="warning" title="Seat limit reached">
    70	          The {seatCheck.plan} plan includes {formatLimit(limits.seats)} seats
    71	          and {seatCheck.used} are in use. Upgrade to invite more teammates.
    72	        </Alert>
    73	      ) : null}
    74	
    75	      <FormField name="email" label="Email" required error={invalid}>
    76	        <Input
    77	          name="email"
    78	          type="email"
    79	          value={email}
    80	          placeholder="teammate@example.com"
    81	          invalid={invalid !== null}
    82	          disabled={seatsExhausted}
    83	          onChange={setEmail}
    84	        />
    85	      </FormField>
    86	
    87	      <FormField name="role" label="Role">
    88	        <RoleSelect
    89	          value={role}
    90	          actor={actor}
    91	          disabled={seatsExhausted}
    92	          onChange={setRole}
    93	        />
    94	      </FormField>
    95	
    96	      <ErrorMessage message={error?.message ?? null} />
    97	
    98	      <Button
    99	        type="button"
   100	        loading={pending}
   101	        disabled={pending || seatsExhausted || email.length === 0}
   102	        onClick={() => void handleSubmit()}
   103	      >
   104	        Send invitation
   105	      </Button>
   106	    </div>
   107	  );
   108	}
