     1	/**
     2	 * Pending invitations, keyed by token hash for the unauthenticated accept flow.
     3	 */
     4	import { and, count, desc, eq, isNull } from "drizzle-orm";
     5	import { newId } from "@/lib/id";
     6	import { getDb, invitations } from "@/server/db";
     7	import { toIsoTimestamp } from "@/types/common";
     8	import { orgPredicate } from "./base-repository";
     9	import { toInvitation } from "./_mappers";
    10	import type { CreateInvitationInput } from "@/schemas/invitation";
    11	import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
    12	import type { Invitation } from "@/types/member";
    13	
    14	const MS_PER_DAY = 24 * 60 * 60 * 1000;
    15	
    16	export async function insertInvitation(
    17	  orgId: OrgId,
    18	  input: CreateInvitationInput,
    19	  invitedBy: UserId,
    20	  tokenHash: string,
    21	): Promise<Invitation> {
    22	  const stamp = toIsoTimestamp(new Date());
    23	  const expiresAt = toIsoTimestamp(
    24	    new Date(Date.now() + input.expiresInDays * MS_PER_DAY),
    25	  );
    26	
    27	  const row = getDb()
    28	    .insert(invitations)
    29	    .values({
    30	      id: newId(),
    31	      orgId,
    32	      email: input.email,
    33	      role: input.role,
    34	      invitedBy,
    35	      tokenHash,
    36	      expiresAt,
    37	      acceptedAt: null,
    38	      revokedAt: null,
    39	      createdAt: stamp,
    40	      updatedAt: stamp,
    41	    })
    42	    .returning()
    43	    .get();
    44	
    45	  return toInvitation(row);
    46	}
    47	
    48	/**
    49	 * The accept flow runs before a session exists, so this is the one read in the
    50	 * repository layer that is not scoped by `orgId` — the token hash is the
    51	 * credential and carries the tenant with it.
    52	 */
    53	export async function findInvitationByTokenHash(
    54	  tokenHash: string,
    55	): Promise<Invitation | null> {
    56	  const row = getDb()
    57	    .select()
    58	    .from(invitations)
    59	    .where(eq(invitations.tokenHash, tokenHash))
    60	    .get();
    61	  return row ? toInvitation(row) : null;
    62	}
    63	
    64	export async function listPendingInvitations(
    65	  orgId: OrgId,
    66	): Promise<readonly Invitation[]> {
    67	  const rows = getDb()
    68	    .select()
    69	    .from(invitations)
    70	    .where(
    71	      and(
    72	        orgPredicate(invitations.orgId, orgId),
    73	        isNull(invitations.acceptedAt),
    74	        isNull(invitations.revokedAt),
    75	      ),
    76	    )
    77	    .orderBy(desc(invitations.createdAt))
    78	    .all();
    79	
    80	  return rows.map(toInvitation);
    81	}
    82	
    83	export async function markInvitationAccepted(
    84	  orgId: OrgId,
    85	  invitationId: InvitationId,
    86	  at: IsoTimestamp,
    87	): Promise<Invitation> {
    88	  const row = getDb()
    89	    .update(invitations)
    90	    .set({ acceptedAt: at, updatedAt: at })
    91	    .where(
    92	      and(
    93	        orgPredicate(invitations.orgId, orgId),
    94	        eq(invitations.id, invitationId),
    95	      ),
    96	    )
    97	    .returning()
    98	    .get();
    99	
   100	  if (!row) throw new Error(`Invitation ${invitationId} not found`);
   101	  return toInvitation(row);
   102	}
   103	
   104	export async function revokeInvitation(
   105	  orgId: OrgId,
   106	  invitationId: InvitationId,
   107	): Promise<Invitation> {
   108	  const stamp = toIsoTimestamp(new Date());
   109	  const row = getDb()
   110	    .update(invitations)
   111	    .set({ revokedAt: stamp, updatedAt: stamp })
   112	    .where(
   113	      and(
   114	        orgPredicate(invitations.orgId, orgId),
   115	        eq(invitations.id, invitationId),
   116	      ),
   117	    )
   118	    .returning()
   119	    .get();
   120	
   121	  if (!row) throw new Error(`Invitation ${invitationId} not found`);
   122	  return toInvitation(row);
   123	}
   124	
   125	/** Pending invites hold a seat, so the seat quota counts them. */
   126	export async function countPendingInvitations(orgId: OrgId): Promise<number> {
   127	  const row = getDb()
   128	    .select({ value: count() })
   129	    .from(invitations)
   130	    .where(
   131	      and(
   132	        orgPredicate(invitations.orgId, orgId),
   133	        isNull(invitations.acceptedAt),
   134	        isNull(invitations.revokedAt),
   135	      ),
   136	    )
   137	    .get();
   138	  return row?.value ?? 0;
   139	}
