    89	      const tags = options.revalidate ?? [];
    90	      if (tags.length > 0) {
    91	        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
    92	      }
    93	
    94	      return stamp({ ok: true, data });
    95	    } catch (error) {
    96	      return stamp(toActionResult(error));
    97	    }
    98	  };
