     8	import {
     9	  createHash,
    10	  randomBytes,
    11	  scrypt,
    12	  timingSafeEqual,
    13	} from "node:crypto";
    14	
    15	const KEY_LENGTH = 64;
    16	const SALT_BYTES = 16;
    17	const PREFIX = "scrypt";
    18	
    19	function deriveKey(password: string, salt: Buffer): Promise<Buffer> {
    20	  return new Promise((resolve, reject) => {
    21	    scrypt(password.normalize("NFKC"), salt, KEY_LENGTH, (error, key) => {
    22	      if (error) reject(error);
    23	      else resolve(key);
    24	    });
    25	  });
    26	}
    27	
    28	/** Returns `scrypt:<saltHex>:<keyHex>` — self-describing, so the verifier
    29	 *  can change parameters later without a migration. */
    30	export async function hashPassword(password: string): Promise<string> {
    31	  const salt = randomBytes(SALT_BYTES);
    32	  const key = await deriveKey(password, salt);
    33	  return `${PREFIX}:${salt.toString("hex")}:${key.toString("hex")}`;
    34	}
    35	
    36	/** Constant-time comparison; a malformed stored hash simply fails to verify. */
    37	export async function verifyPassword(
    38	  password: string,
    39	  hash: string,
    40	): Promise<boolean> {
    41	  const [scheme, saltHex, keyHex] = hash.split(":");
    42	  if (scheme !== PREFIX || !saltHex || !keyHex) return false;
    43	
    44	  const expected = Buffer.from(keyHex, "hex");
    45	  if (expected.length !== KEY_LENGTH) return false;
    46	
    47	  const actual = await deriveKey(password, Buffer.from(saltHex, "hex"));
    48	  return timingSafeEqual(actual, expected);
    49	}
